mapper.select:
SELECT artag.article_id, t.name AS tag_name FROM tb_article_tag artag INNER JOIN tb_tag t ON artag.tag_id = t.id WHERE artag.article_id IN
#{articleId}
ORDER BY artag.article_id ASC, t.id ASC

SELECT t.id, t.name, t.article_count FROM ( SELECT c.id, c.name, COUNT(a.id) AS article_count FROM tb_category c LEFT JOIN tb_article a ON a.category_id = c.id
AND c.name LIKE CONCAT('%', #{name}, '%')
GROUP BY c.id, c.name ) t
AND t.article_count >= #{minCount}
AND t.article_count <= #{maxCount}
ORDER BY t.article_count DESC, t.id ASC
